const toggle=document.getElementById('search-toggle'),panel=document.getElementById('search-panel');toggle.addEventListener('click',()=>{panel.classList.toggle('hidden');document.getElementById('search-input').focus()});document.getElementById('search-close').addEventListener('click',()=>panel.classList.add('hidden'));document.getElementById('search-input').addEventListener('input',e=>{const q=e.target.value.toLowerCase();const hits=articles.filter(a=>(a.title+' '+a.desc+' '+a.cat).toLowerCase().includes(q));document.getElementById('article-list').innerHTML=renderCards(hits)});
